import { ChangeDetectionStrategy, Component, inject, output, signal } from '@angular/core';
import { TranslatePipe, TranslateService } from '@ngx-translate/core';
import { ItemService } from '@org/api-services';
import { messageForError } from '@org/interceptors';
import { ItemFields } from '@org/shared-models';
import { CardComponent, CloseButtonComponent } from '@org/ui';
import { ItemFormComponent } from './item-form';

/**
 * The form for a new item, shown in the panel beside the list (platform U10, item spec R2-R7). The code is generated by the
 * server (R10). It reports the created item's id; the page opens it, where the barcodes are added (R6).
 */
@Component({
  selector: 'app-item-add',
  standalone: true,
  imports: [TranslatePipe, CardComponent, CloseButtonComponent, ItemFormComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="flex flex-col gap-5">
      <div class="flex items-center gap-3">
        <h1 class="mr-auto text-xl font-semibold text-primary-fg">{{ 'item.add.title' | translate }}</h1>
        <app-close-button [label]="'item.close' | translate" (clicked)="closed.emit()" />
      </div>
      <app-card>
        <app-item-form [saving]="saving()" [error]="error()" submitLabel="item.add.submit" (submitted)="add($event)" (cancelled)="closed.emit()" />
      </app-card>
    </div>
  `,
})
export class ItemAddComponent {
  private readonly items = inject(ItemService);
  private readonly translate = inject(TranslateService);

  readonly created = output<string>();
  readonly closed = output<void>();

  readonly saving = signal(false);
  readonly error = signal('');

  add(fields: ItemFields): void {
    this.saving.set(true);
    this.error.set('');
    this.items.create(fields).subscribe({
      next: (item) => {
        this.saving.set(false);
        this.created.emit(item.id);
      },
      error: (error: unknown) => {
        this.saving.set(false);
        this.error.set(messageForError(error, this.translate));
      },
    });
  }
}
